import json
from pathlib import Path
rows=json.loads(Path('all-games-data.json').read_text());sample=json.loads(Path('engine-sample.json').read_text())
for r in rows:r.pop('pgn',None)
html='''<!doctype html><html lang="he" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>דוח השיפור של מאיר</title><style>*{box-sizing:border-box}body{margin:0;background:#232420;color:#f1f0e9;font:16px system-ui;line-height:1.7}main{max-width:1100px;margin:auto;padding:28px}a{color:#bbd99a}h1{font-size:32px;margin-bottom:4px}h2{font-size:22px}.muted{color:#b8bab0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card,section{background:#30322c;border:1px solid #ffffff0c;border-radius:12px;padding:20px;margin-bottom:18px}.card b{display:block;font-size:29px;color:#c3dda4}select{font:inherit;padding:10px;background:#3b4035;color:white;border:0;border-radius:7px;margin:5px;min-height:44px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:right;padding:10px;border-bottom:1px solid #ffffff12}svg{width:100%;height:180px}.bar{height:12px;background:#6d924f;border-radius:3px}.tag{color:#e5c786}li{margin-bottom:8px}.scroll{overflow:auto}@media(max-width:700px){main{padding:14px}.cards{grid-template-columns:1fr 1fr}h1{font-size:26px}section{padding:14px}}</style><main><a href="chess.html">חזרה למשחק</a><h1>דוח השיפור שלך</h1><p class="muted">meirco1997 · ארכיון שנשלף ב־5.10.2026</p><section><b>היקף ודיוק הדוח</b><p>2,658 רשומות שונות מתוך 2,660 שמוצגות באתר. 2,654 משחקים פוענחו בחוקים הרגילים; 4 רשומות חריגות נשמרו בארכיון אך אינן נכללות במדדי מהלכים. נתוני הארכיון כוללים משחקים מאז 2023. ניתוח המנוע כולל מדגם של 20 המשחקים האחרונים מול אנשים עם לפחות 10 חצאי־מסעים, ב־Stockfish 10 בעומק 10.</p><p class="muted">הסטטיסטיקות אינן ציוני CAPS2 או דירוגי קטגוריות של Chess.com. פילוח פתיחות כאן הוא משפחת פתיחה לפי המסעים הראשונים; לא סיווג ECO מלא. נתוני בוטים מסומנים לפי שם היריב. אין נתוני השוואה לשחקנים אחרים או דירוג טקטיקה משוער.</p><a href="meirco1997-all-games.pgn">הורדת ארכיון PGN</a></section><div><label>יריב <select id="type"><option value="human">אנשים</option><option value="all">כולם</option><option value="bot">בוטים</option></select></label><label>צבע <select id="color"><option value="all">שני הצבעים</option><option value="w">לבן</option><option value="b">שחור</option></select></label><label>קצב <select id="tc"><option value="all">כל הקצבים</option></select></label></div><div class="cards" id="cards"></div><section><h2>תוצאות לאורך השנים</h2><div id="years"></div></section><section><h2>תוצאות לפי צבע וקצב</h2><div class="scroll" id="splits"></div></section><section><h2>הצרחה ובטיחות המלך</h2><div id="castle"></div><p class="muted">הקשר בין הצרחה לניצחונות אינו מוכיח סיבה: משחקים קצרים, קצב וסגנון היריב משפיעים גם הם.</p></section><section><h2>משפחות פתיחה</h2><div class="scroll" id="openings"></div></section><section><h2>איך מסתיימים ההפסדים שלך?</h2><div id="endings"></div></section><section><h2>ניתוח מנוע — 20 משחקים אחרונים מול אנשים</h2><div id="engine"></div><p class="muted">המדגם הזה קבוע ואינו משתנה לפי המסננים למעלה. ספים: אי־דיוק 50–99, טעות 100–199, טעות חמורה 200 ומעלה מאיות רגלי. מצבי מט מוגבלים ל־1,000 לצורך הממוצע; בדיקה עמוקה יותר עשויה לשנות סיווגים.</p></section><section><h2>תוכנית האימון שלך</h2><ol><li><b>חמש דקות ביום: איומי מט.</b> בכל עמדה בדוק את השחים וההכאות של היריב, במיוחד ליד f2/f7 והאלכסון אל המלך.</li><li><b>עשר דקות: משחק 10+5 או 15+10.</b> לפני לחיצה שאל: מה השתנה במהלך האחרון? מה היריב יעשה מיד אחריי?</li><li><b>חמש דקות: תיקון שתי טעויות מהמשחק.</b> שחזר את העמדה לפני הטעות, מצא חלופה בעצמך ואז השווה למנוע.</li><li><b>פתיחות עקביות.</b> בחר פתיחה אחת בלבן ותשובה אחת ל־e4 ול־d4 בשחור. שאף לפתח את שני הפרשים והרצים ולהצריח לפני התקפות רגלים ליד המלך.</li></ol><p>אחרי עשרה משחקים בקצב איטי, השווה מחדש הפסדי מט מוקדמים, אובדן הערכה בפתיחה ונטישות. זו תוכנית ראשונית מהארכיון והמדגם, לא דירוג מקצועי.</p></section><section><h2>מה מציעים למנויים ב־Chess.com?</h2><p><a href="https://support.chess.com/en/articles/8708925-what-is-insights-on-chess-com">Insights</a> למנויי Diamond כולל תוצאות, פתיחות, הצרחות, איכות מהלכים, טקטיקות שנמצאו או הוחמצו וניתוח לפי זמן. <a href="https://support.chess.com/en/articles/15451190-how-do-i-use-advanced-stats">Advanced Stats</a> מוסיף קטגוריות פתיחות, טקטיקה, אסטרטגיה וסיומים והשוואה לשחקנים ברמה דומה. Insights מסנן משחקים נגד מחשב, וריאנטים ומשחקים קצרים.</p></section></main><script>const rows=__ROWS__,sample=__SAMPLE__;
const $=id=>document.getElementById(id),percent=(n,d)=>d?(100*n/d).toFixed(1)+'%':'—',count=(r,result)=>r.filter(x=>x.result===result).length;
for(const tc of [...new Set(rows.filter(r=>r.valid).map(r=>r.tc))].sort()){let o=document.createElement('option');o.value=tc;o.textContent=tc==='0'?'ללא שעון':tc;$('tc').append(o)}
function table(groups){return '<table><thead><tr><th>קבוצה</th><th>משחקים</th><th>ניצחונות</th><th>הפסדים</th><th>תיקו</th><th>שיעור ניצחון</th></tr></thead><tbody>'+groups.map(([name,r])=>`<tr><td>${name}</td><td>${r.length}</td><td>${count(r,'win')}</td><td>${count(r,'loss')}</td><td>${count(r,'draw')}</td><td>${percent(count(r,'win'),r.length)}</td></tr>`).join('')+'</tbody></table>'}
function grouping(r,key){const g={};for(const x of r)(g[key(x)]??=[]).push(x);return Object.entries(g)}
function update(){const r=rows.filter(x=>x.valid&&($('type').value==='all'||x.bot===($('type').value==='bot'))&&($('color').value==='all'||x.color===$('color').value)&&($('tc').value==='all'||x.tc===$('tc').value));const losses=r.filter(x=>x.result==='loss'),early=losses.filter(x=>x.earlyMate);$('cards').innerHTML=[['משחקים',r.length],['ניצחונות',percent(count(r,'win'),r.length)],['הפסדים',count(r,'loss')],['מט עד מסע 20',early.length]].map(([a,b])=>`<div class="card">${a}<b>${b}</b></div>`).join('');$('years').innerHTML=table(grouping(r,x=>x.date.slice(0,4)||'תאריך חסר').sort());$('splits').innerHTML=table([['לבן',r.filter(x=>x.color==='w')],['שחור',r.filter(x=>x.color==='b')],...grouping(r,x=>'קצב '+x.tc).sort((a,b)=>b[1].length-a[1].length)]);$('castle').innerHTML=table([['הצרחה עד מסע 10',r.filter(x=>x.castle!==null&&x.castle<=10)],['הצרחה מאוחרת',r.filter(x=>x.castle>10)],['ללא הצרחה',r.filter(x=>x.castle===null)]])+`<p>${early.length} הפסדים במט עד מסע 20 מתוך ${losses.length} הפסדים (${percent(early.length,losses.length)}).</p>`;$('openings').innerHTML=table(grouping(r,x=>x.opening).sort((a,b)=>b[1].length-a[1].length));const end=grouping(losses,x=>x.termination.includes('ננטש')?'נטישה':x.termination.includes('זמנו')||x.termination.includes('זמן')?'הזמן אזל':x.mate?'מט':x.termination.includes('נכנע')?'כניעה':'אחר');$('endings').innerHTML=end.map(([name,g])=>`<p>${name}: ${g.length} (${percent(g.length,losses.length)})</p><div class="bar" style="width:${100*g.length/Math.max(1,losses.length)}%"></div>`).join('')}
for(const id of ['type','color','tc'])$(id).onchange=update;
const moves=sample.flatMap(g=>g.analyses.map(m=>({...m,date:g.date,opponent:g.opponent})));$('engine').innerHTML=`<p>${moves.length} מהלכים שלך נבדקו. ${moves.filter(m=>m.loss>=200).length} טעויות חמורות, ${moves.filter(m=>m.loss>=100&&m.loss<200).length} טעויות, ${moves.filter(m=>m.loss>=50&&m.loss<100).length} אי־דיוקים.</p>`+'<table><tr><th>שלב</th><th>מהלכים</th><th>אובדן ממוצע במאיות רגלי</th></tr>'+grouping(moves,x=>x.phase).map(([name,r])=>`<tr><td>${name}</td><td>${r.length}</td><td>${Math.round(r.reduce((a,m)=>a+m.loss,0)/r.length)}</td></tr>`).join('')+'</table><h3>עמדות לתרגול מהמדגם</h3>'+moves.filter(m=>m.loss>=200).sort((a,b)=>b.loss-a.loss).slice(0,8).map(m=>`<p><span class="tag">${m.date} · מול ${m.opponent}</span><br>מסע ${m.move}: שיחקת <bdi>${m.san}</bdi>, המנוע מציע <bdi>${m.best}</bdi>. אובדן: ${(m.loss/100).toFixed(2)} רגלים.</p>`).join('');update();</script><script src="sync-core.js?v=2"></script><script src="sync.js?v=3"></script></html>'''
Path('insights.html').write_text(html.replace('__ROWS__',json.dumps(rows,ensure_ascii=False)).replace('__SAMPLE__',json.dumps(sample,ensure_ascii=False)))
